const event = $json.body.events?.[0];

if (!event || event.type !== "message") {
  return [];
}

const message = event.message?.text || "";
const replyToken = event.replyToken;

// รูปแบบที่รองรับ:
// จาก ตลาดน้อย ไป คณะวิศวกรรมศาสตร์
const match = message.match(/^จาก\s+(.+?)\s+ไป\s+(.+)$/);

if (!match) {
  return [
    {
      json: {
        replyToken,
        command: message,
        valid: false,
        text: "กรุณาพิมพ์ในรูปแบบ\nจาก [ต้นทาง] ไป [ปลายทาง]\n\nตัวอย่าง\nจาก ตลาดน้อย ไป คณะวิศวกรรมศาสตร์"
      }
    }
  ];
}

const origin = match[1].trim();
const destination = match[2].trim();

return [
  {
    json: {
      replyToken,
      command: message,
      origin,
      destination,
      valid: true
    }
  }
];

// ==========================================
// ค้นหาเส้นทางจาก LINE - MSU Smart Bus
// รองรับเส้นทางวนรอบ
// ==========================================

// ดึงข้อมูลป้ายทั้งหมด
const stops = $('ดึงข้อมูลป้าย MSU')
  .all()
  .map(item => item.json);

// ดึงคำสั่งจาก LINE
const command = $('แยกคำสั่ง LINE').first().json;


// ==========================================
// ตรวจสอบคำสั่ง
// ==========================================

if (!command.valid) {

  return [{
    json: {
      replyToken: command.replyToken || "",
      text: command.text || "❌ รูปแบบคำสั่งไม่ถูกต้อง"
    }
  }];

}


// ==========================================
// รับต้นทาง / ปลายทาง
// ==========================================

let origin = String(command.origin || "").trim();
let destination = String(command.destination || "").trim();

const replyToken = command.replyToken || "";


// ==========================================
// Alias ชื่อป้าย
// ==========================================

const aliases = {

  "วิศวกรรมศาสตร์": "คณะวิศวกรรมศาสตร์",

  "เภสัชศาสตร์": "หน้าคณะเภสัชศาสตร์",

  "อธิการบดี": "สำนักงานอธิการบดี",

  "ราชนครินทร์": "หน้าอาคารราชนครินทร์",

  "โรงอาหาร": "โรงอาหาร ม.เก่า",

  "การท่องเที่ยว": "คณะการท่องเที่ยว",

  "คอนโด 3": "ป้อมยามหน้าคอนโด 3",

  "โรงเรียนสาธิต":
    "หน้าโรงเรียนสาธิต มมส. (ฝ่ายประถม)",

  "โรงพยาบาลสุทธาเวช":
    "ข้างโรงพยาบาลสุทธาเวช",

  "การบัญชี": "แยกคณะการบัญชีฯ",

  "ตลาด": "ตลาดน้อย",

  "พลาซ่า": "พลาซ่า",

  "คอนโดบุคลากร": "คอนโดบุคลากร",

  "สถานีชาร์จ": "สถานีชาร์จ"

};


// ==========================================
// แปลง Alias
// ==========================================

origin = aliases[origin] || origin;
destination = aliases[destination] || destination;


// ==========================================
// ฟังก์ชันแปลง sequence เป็นตัวเลข
// ==========================================

function seq(stop) {
  return Number(stop.sequence);
}


// ==========================================
// ค้นหาป้ายต้นทาง / ปลายทาง
// ==========================================

const originStops = stops.filter(
  stop => stop.stop_name === origin
);

const destinationStops = stops.filter(
  stop => stop.stop_name === destination
);


// ==========================================
// ไม่พบต้นทาง
// ==========================================

if (originStops.length === 0) {

  return [{
    json: {
      replyToken,

      text:
        `❌ ไม่พบป้ายต้นทาง

📍 ต้นทาง: ${command.origin}

กรุณาตรวจสอบชื่อป้ายอีกครั้ง`
    }
  }];

}


// ==========================================
// ไม่พบปลายทาง
// ==========================================

if (destinationStops.length === 0) {

  return [{
    json: {
      replyToken,

      text:
        `❌ ไม่พบป้ายปลายทาง

🎯 ปลายทาง: ${command.destination}

กรุณาตรวจสอบชื่อป้ายอีกครั้ง`
    }
  }];

}


// ==========================================
// ค้นหาเส้นทาง
// ==========================================

const results = [];


// ==========================================
// วนทุกคู่ต้นทาง / ปลายทาง
// ==========================================

for (const originStop of originStops) {

  for (const destinationStop of destinationStops) {

    // ต้องเป็นสายเดียวกัน
    if (
      originStop.route_id !==
      destinationStop.route_id
    ) {
      continue;
    }


    // ========================================
    // ป้ายทั้งหมดของสายนี้
    // ========================================

    const routeStops = stops
      .filter(
        stop =>
          stop.route_id === originStop.route_id
      )
      .sort(
        (a, b) =>
          seq(a) - seq(b)
      );


    if (routeStops.length === 0) {
      continue;
    }


    // ========================================
    // ตำแหน่งต้นทาง / ปลายทาง
    // ========================================

    const originIndex =
      routeStops.findIndex(
        stop =>
          stop.stop_id === originStop.stop_id
      );

    const destinationIndex =
      routeStops.findIndex(
        stop =>
          stop.stop_id === destinationStop.stop_id
      );


    if (
      originIndex === -1 ||
      destinationIndex === -1
    ) {
      continue;
    }


    // ========================================
    // คำนวณจำนวนป้ายแบบวนรอบ
    // ========================================

    let stopCount;

    if (destinationIndex >= originIndex) {

      // ปลายทางอยู่ข้างหน้า
      stopCount =
        destinationIndex -
        originIndex;

    } else {

      // ปลายทางอยู่หลัง
      // ต้องวนกลับต้นเส้นทาง
      stopCount =
        routeStops.length -
        originIndex +
        destinationIndex;

    }


    // ========================================
    // สร้างรายการป้ายตั้งแต่ต้นทาง
    // ถึงปลายทาง
    // ========================================

    const selectedStops = [];

    let currentIndex = originIndex;

    let safetyCounter = 0;

    while (true) {

      selectedStops.push(
        routeStops[currentIndex]
      );

      if (
        currentIndex ===
        destinationIndex
      ) {
        break;
      }

      currentIndex++;

      if (
        currentIndex >=
        routeStops.length
      ) {
        currentIndex = 0;
      }

      safetyCounter++;

      // ป้องกัน loop ผิดพลาด
      if (
        safetyCounter >
        routeStops.length
      ) {
        break;
      }

    }


    // ========================================
    // ชื่อสายรถ
    // ========================================

    let routeName;

    if (originStop.route_id === "RED") {

      routeName = "🔴 สายสีแดง";

    } else if (
      originStop.route_id === "BLUE"
    ) {

      routeName = "🔵 สายสีน้ำเงิน";

    } else {

      routeName =
        `สาย ${originStop.route_id}`;

    }


    // ========================================
    // บันทึกผลลัพธ์
    // ========================================

    results.push({

      json: {

        replyToken,

        origin:
          command.origin,

        destination:
          command.destination,

        origin_normalized:
          origin,

        destination_normalized:
          destination,

        route_id:
          originStop.route_id,

        route_name:
          routeName,

        origin_stop_id:
          originStop.stop_id,

        destination_stop_id:
          destinationStop.stop_id,

        origin_sequence:
          seq(originStop),

        destination_sequence:
          seq(destinationStop),

        stop_count:
          stopCount,

        // ป้ายทั้งหมดที่ต้องผ่าน
        route_stops:
          selectedStops.map(stop => ({

            stop_id:
              stop.stop_id,

            stop_name:
              stop.stop_name,

            sequence:
              seq(stop)

          }))

      }

    });

  }

}


// ==========================================
// ไม่พบเส้นทาง
// ==========================================

if (results.length === 0) {

  return [{
    json: {

      replyToken,

      origin:
        command.origin,

      destination:
        command.destination,

      text:
        `❌ ไม่พบเส้นทาง

📍 ต้นทาง: ${command.origin}
🎯 ปลายทาง: ${command.destination}

กรุณาตรวจสอบว่าทั้งสองป้ายอยู่ในเส้นทางรถเดียวกัน`

    }
  }];

}


// ==========================================
// เลือกเส้นทางที่มีจำนวนป้ายน้อยที่สุด
// ==========================================

results.sort(
  (a, b) =>
    a.json.stop_count -
    b.json.stop_count
);


// ==========================================
// ส่งเส้นทางที่เหมาะสมที่สุดกลับไป
// ==========================================

return [results[0]];

// ==========================================
// คำนวณระยะทางระหว่างป้ายรถ
// ใช้สูตร Haversine
// ==========================================

const stops = $input.all().map(item => item.json);


// ------------------------------------------
// ฟังก์ชันคำนวณระยะทางจาก Latitude/Longitude
// ผลลัพธ์เป็นกิโลเมตร
// ------------------------------------------

function calculateDistance(lat1, lon1, lat2, lon2) {

  const R = 6371; // รัศมีโลก km

  const dLat =
    (lat2 - lat1) * Math.PI / 180;

  const dLon =
    (lon2 - lon1) * Math.PI / 180;

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) *
    Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;

  const c =
    2 * Math.atan2(
      Math.sqrt(a),
      Math.sqrt(1 - a)
    );

  return R * c;
}


// ------------------------------------------
// เรียงป้ายตามสายและลำดับ
// ------------------------------------------

const sortedStops = [...stops].sort((a, b) => {

  if (a.route_id !== b.route_id) {

    return a.route_id.localeCompare(b.route_id);

  }

  return Number(a.sequence) -
         Number(b.sequence);
});


// ------------------------------------------
// คำนวณระยะทางระหว่างป้ายติดกัน
// ------------------------------------------

const results = [];

for (let i = 0; i < sortedStops.length; i++) {

  const current = sortedStops[i];

  const next = sortedStops[i + 1];


  // ถ้าไม่มีป้ายถัดไป
  if (!next) {
    continue;
  }


  // ต้องเป็นสายเดียวกัน
  if (
    current.route_id !== next.route_id
  ) {
    continue;
  }


  // ตรวจสอบพิกัด
  if (
    current.latitude == null ||
    current.longitude == null ||
    next.latitude == null ||
    next.longitude == null
  ) {

    results.push({

      json: {

        route_id:
          current.route_id,

        from_stop_id:
          current.stop_id,

        from_stop_name:
          current.stop_name,

        to_stop_id:
          next.stop_id,

        to_stop_name:
          next.stop_name,

        distance_km:
          null,

        status:
          "ไม่มีพิกัด"

      }

    });

    continue;
  }


  // ----------------------------------------
  // คำนวณระยะทาง
  // ----------------------------------------

  const distanceKm =
    calculateDistance(
      Number(current.latitude),
      Number(current.longitude),
      Number(next.latitude),
      Number(next.longitude)
    );


  results.push({

    json: {

      route_id:
        current.route_id,

      from_stop_id:
        current.stop_id,

      from_stop_name:
        current.stop_name,

      to_stop_id:
        next.stop_id,

      to_stop_name:
        next.stop_name,

      distance_km:
        Number(distanceKm.toFixed(3)),

      status:
        "คำนวณสำเร็จ"

    }

  });
}


return results;

// ========================================
// คำนวณระยะทางจากรถถึงปลายทาง
// ใช้ Latitude / Longitude ของป้ายจริง
// ========================================

const busData = $input.first().json;

// ดึงข้อมูลป้ายทั้งหมด
const stops = $('ดึงข้อมูลป้าย MSU')
  .all()
  .map(item => item.json);


// ========================================
// ฟังก์ชัน Haversine
// ใช้คำนวณระยะทางระหว่างพิกัด GPS
// ========================================

function haversine(lat1, lon1, lat2, lon2) {

  const R = 6371; // รัศมีโลก km

  const dLat =
    (lat2 - lat1) * Math.PI / 180;

  const dLon =
    (lon2 - lon1) * Math.PI / 180;

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) *
    Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;

  const c =
    2 * Math.atan2(
      Math.sqrt(a),
      Math.sqrt(1 - a)
    );

  return R * c;
}


// ========================================
// ตรวจสอบข้อมูล
// ========================================

const routeId =
  busData.route_id;

const currentStopId =
  busData.current_stop_id;

const destinationStopId =
  busData.destination_stop_id;


if (!routeId ||
    !currentStopId ||
    !destinationStopId) {

  return [{
    json: {
      ...busData,
      error: "ข้อมูลป้ายสำหรับคำนวณระยะทางไม่ครบ"
    }
  }];
}


// ========================================
// เอาเฉพาะป้ายของสายรถ
// ========================================

const routeStops = stops
  .filter(stop =>
    stop.route_id === routeId
  )
  .sort(
    (a, b) =>
      Number(a.sequence) -
      Number(b.sequence)
  );


// หาตำแหน่งปัจจุบันและปลายทาง
const currentIndex =
  routeStops.findIndex(
    stop =>
      stop.stop_id === currentStopId
  );

const destinationIndex =
  routeStops.findIndex(
    stop =>
      stop.stop_id === destinationStopId
  );


if (
  currentIndex === -1 ||
  destinationIndex === -1
) {

  return [{
    json: {
      ...busData,
      error: "ไม่พบป้ายในสายรถ"
    }
  }];
}


// ========================================
// คำนวณระยะทาง
// ========================================

let totalDistance = 0;


// กรณีอยู่ป้ายเดียวกัน
if (currentIndex === destinationIndex) {

  totalDistance = 0;

}


// กรณีปลายทางอยู่ข้างหน้า
else if (destinationIndex > currentIndex) {

  for (
    let i = currentIndex;
    i < destinationIndex;
    i++
  ) {

    const from = routeStops[i];
    const to = routeStops[i + 1];

    const lat1 = Number(from.latitude);
    const lon1 = Number(from.longitude);

    const lat2 = Number(to.latitude);
    const lon2 = Number(to.longitude);

    if (
      !Number.isFinite(lat1) ||
      !Number.isFinite(lon1) ||
      !Number.isFinite(lat2) ||
      !Number.isFinite(lon2)
    ) {

      return [{
        json: {
          ...busData,
          error:
            `ป้าย ${from.stop_name} หรือ ${to.stop_name} ไม่มีพิกัด`
        }
      }];
    }

    totalDistance +=
      haversine(
        lat1,
        lon1,
        lat2,
        lon2
      );
  }

}


// ========================================
// กรณีปลายทางอยู่ก่อนหน้า
// รถวิ่งเป็นวงรอบ
// ========================================

else {

  // จากปัจจุบัน → ป้ายสุดท้าย
  for (
    let i = currentIndex;
    i < routeStops.length - 1;
    i++
  ) {

    const from = routeStops[i];
    const to = routeStops[i + 1];

    totalDistance +=
      haversine(
        Number(from.latitude),
        Number(from.longitude),
        Number(to.latitude),
        Number(to.longitude)
      );
  }


  // จากป้ายแรก → ปลายทาง
  for (
    let i = 0;
    i < destinationIndex;
    i++
  ) {

    const from = routeStops[i];
    const to = routeStops[i + 1];

    totalDistance +=
      haversine(
        Number(from.latitude),
        Number(from.longitude),
        Number(to.latitude),
        Number(to.longitude)
      );
  }
}


// ========================================
// ส่งผลลัพธ์
// ========================================

return [{
  json: {
    ...busData,

    total_distance_km:
      Number(totalDistance.toFixed(3)),

    distance_calculation:
      "Haversine Latitude/Longitude"
  }
}];

// ========================================
// ข้อมูลจาก Random Forest
// ========================================

const prediction = $('ทำนาย ETA Random Forest')
  .first()
  .json;


// ========================================
// ข้อมูลรถและเส้นทาง
// ========================================

const source = $('คำนวณระยะทางถึงปลายทาง')
  .first()
  .json;


// ========================================
// ข้อมูล LINE
// ========================================

const routeData = $('ค้นหาเส้นทางจาก LINE')
  .first()
  .json;


// ========================================
// ชื่อสาย
// ========================================

let routeName = "ไม่ทราบสาย";

if (source.route_id === "RED") {
  routeName = "🔴 สายสีแดง";
}

if (source.route_id === "BLUE") {
  routeName = "🔵 สายสีน้ำเงิน";
}


// ========================================
// ระยะทาง
// ========================================

const distance = Number(
  source.total_distance_km ??
  source.distance_km ??
  prediction.distance_km ??
  0
);


// ========================================
// ETA จาก Random Forest
// ========================================

const predictedETA = Number(
  prediction.predicted_eta_minutes
) || 0;


// ========================================
// จำนวนป้ายที่เหลือ
// ========================================

const remainingStops = Number(
  source.remaining_stops
) || 0;


// ========================================
// ความเร็ว
// ========================================

const speed = Number(
  source.speed_kmh
) || 0;


// ========================================
// สร้างข้อความ LINE
// ========================================

const text = `🚌 MSU EV Bus

${routeName}

📍 รถอยู่ที่
${source.current_stop_name || "-"}

🎯 ปลายทาง
${source.destination_stop_name ||
 routeData.destination ||
 "-"}

📏 ระยะทางประมาณ
${distance.toFixed(3)} กม.

🚍 ความเร็วรถ
${speed.toFixed(1)} กม./ชม.

🤖 ETA จาก Random Forest
ประมาณ ${predictedETA.toFixed(2)} นาที

🚏 เหลือประมาณ
${remainingStops} ป้าย

🕐 อัปเดต
${new Date().toLocaleString("th-TH")}`;


// ========================================
// OUTPUT
// ========================================

return [{
  json: {

    replyToken:
      source.replyToken ||
      routeData.replyToken ||
      "",

    route_id:
      source.route_id,

    bus_id:
      source.bus_id,

    text,

    // เก็บข้อมูลไว้ตรวจสอบด้วย
    distance_km:
      distance,

    predicted_eta_minutes:
      predictedETA,

    remaining_stops:
      remainingStops

  }
}];

// ========================================
// คำนวณป้ายที่เหลือ + เลือกรถที่ใกล้ปลายทางที่สุด
// MSU Smart Bus
// ========================================

const inputBuses = $input.all().map(item => item.json);

const stops = $('ดึงข้อมูลป้าย MSU')
  .all()
  .map(item => item.json);

const routeData = $('ค้นหาเส้นทางจาก LINE')
  .first()
  .json;


// ========================================
// 1. เลือกรถข้อมูลล่าสุดของแต่ละคัน
// ========================================

const latestBuses = new Map();

for (const bus of inputBuses) {

  if (!bus.bus_id) continue;

  const currentTime = new Date(
    bus.timestamp ||
    bus.updatedAt ||
    bus.createdAt ||
    0
  ).getTime();

  const oldBus = latestBuses.get(bus.bus_id);

  if (!oldBus) {

    latestBuses.set(bus.bus_id, bus);

    continue;
  }

  const oldTime = new Date(
    oldBus.timestamp ||
    oldBus.updatedAt ||
    oldBus.createdAt ||
    0
  ).getTime();

  if (currentTime >= oldTime) {
    latestBuses.set(bus.bus_id, bus);
  }
}


// ========================================
// 2. คำนวณป้ายที่เหลือของรถแต่ละคัน
// ========================================

const results = [];

for (const bus of latestBuses.values()) {

  // รถต้องเป็นสายเดียวกับเส้นทางที่ผู้ใช้ค้นหา
  if (bus.route_id !== routeData.route_id) {
    continue;
  }


  // ----------------------------------------
  // เรียงป้ายตามลำดับ
  // ----------------------------------------

  const routeStops = stops
    .filter(stop => stop.route_id === bus.route_id)
    .sort(
      (a, b) =>
        Number(a.sequence) -
        Number(b.sequence)
    );


  if (routeStops.length === 0) {
    continue;
  }


  // ----------------------------------------
  // หาตำแหน่งรถปัจจุบัน
  // ----------------------------------------

  const currentIndex = routeStops.findIndex(
    stop =>
      stop.stop_id === bus.current_stop_id
  );


  // ----------------------------------------
  // หาตำแหน่งปลายทาง
  // ----------------------------------------

  const destinationIndex = routeStops.findIndex(
    stop =>
      stop.stop_id === routeData.destination_stop_id
  );


  if (
    currentIndex === -1 ||
    destinationIndex === -1
  ) {
    continue;
  }


  const currentStop =
    routeStops[currentIndex];

  const destinationStop =
    routeStops[destinationIndex];


  // ========================================
  // 3. คำนวณจำนวนป้ายแบบ "วนรอบ"
  // ========================================

  let remainingStops =
    (destinationIndex - currentIndex + routeStops.length)
    % routeStops.length;


  // ถ้ารถอยู่ที่ปลายทางแล้ว
  if (currentIndex === destinationIndex) {
    remainingStops = 0;
  }


  // ========================================
  // 4. คำนวณระยะทางแบบประมาณ
  // ========================================

  let totalDistanceKm = 0;

  let index = currentIndex;

  while (index !== destinationIndex) {

    const nextIndex =
      (index + 1) % routeStops.length;

    const from = routeStops[index];
    const to = routeStops[nextIndex];


    // Haversine
    const R = 6371;

    const lat1 =
      Number(from.latitude) * Math.PI / 180;

    const lat2 =
      Number(to.latitude) * Math.PI / 180;

    const dLat =
      (Number(to.latitude) -
       Number(from.latitude)) *
      Math.PI / 180;

    const dLon =
      (Number(to.longitude) -
       Number(from.longitude)) *
      Math.PI / 180;


    const a =
      Math.sin(dLat / 2) ** 2 +
      Math.cos(lat1) *
      Math.cos(lat2) *
      Math.sin(dLon / 2) ** 2;

    const c =
      2 * Math.atan2(
        Math.sqrt(a),
        Math.sqrt(1 - a)
      );

    const distance =
      R * c;


    totalDistanceKm += distance;

    index = nextIndex;


    // ป้องกัน loop ผิดพลาด
    if (remainingStops === 0) {
      break;
    }
  }


  // ========================================
  // 5. สร้างข้อมูลรถ
  // ========================================

  results.push({

    json: {

      replyToken:
        routeData.replyToken || "",

      origin:
        routeData.origin,

      destination:
        routeData.destination,

      bus_id:
        bus.bus_id,

      route_id:
        bus.route_id,

      current_stop_id:
        bus.current_stop_id,

      current_stop_name:
        currentStop.stop_name,

      destination_stop_id:
        destinationStop.stop_id,

      destination_stop_name:
        destinationStop.stop_name,

      current_sequence:
        Number(currentStop.sequence),

      destination_sequence:
        Number(destinationStop.sequence),

      remaining_stops:
        remainingStops,

      speed_kmh:
        Number(bus.speed_kmh) || 0,

      latitude:
        Number(bus.latitude),

      longitude:
        Number(bus.longitude),

      total_distance_km:
        Number(totalDistanceKm.toFixed(3)),

      timestamp:
        bus.timestamp

    }

  });

}


