// ฟังก์ชันสุ่มความเร็วเล็กน้อย
function randomSpeed(baseSpeed) {
  const variation = (Math.random() * 4) - 2;
  return Number((baseSpeed + variation).toFixed(1));
}

// ฟังก์ชันสร้างข้อมูลรถ
function updateBus(bus) {

  const routeId = bus.route_id;

  // เลือกป้ายของสายรถ
  const routeStops = stops
    .filter(stop => stop.route_id === routeId)
    .sort((a, b) => Number(a.sequence) - Number(b.sequence));

  if (routeStops.length === 0) {
    return {
      json: {
        ...bus,
        error: `ไม่พบข้อมูลป้ายของสาย ${routeId}`
      }
    };
  }

  // ใช้ current_stop_id เดิม
  let currentStopIndex = routeStops.findIndex(
    stop => stop.stop_id === bus.current_stop_id
  );

  // ถ้าไม่พบ ให้เริ่มจากป้ายแรก
  if (currentStopIndex < 0) {
    currentStopIndex = 0;
  }

  // จำลองให้รถขยับไปป้ายถัดไป
  let nextStopIndex = currentStopIndex + 1;

  // ถ้าถึงป้ายสุดท้าย ให้กลับไปป้ายแรก
  if (nextStopIndex >= routeStops.length) {
    nextStopIndex = 0;
  }

  const currentStop = routeStops[nextStopIndex];

  return {
    json: {
      bus_id: bus.bus_id,
      route_id: bus.route_id,

      // ใช้พิกัดจริงของป้ายจาก Data Table
      latitude: Number(currentStop.latitude),
      longitude: Number(currentStop.longitude),

      // ความเร็วจำลอง
      speed_kmh: randomSpeed(
        routeId === "RED" ? 20 : 18
      ),

      // ป้ายปัจจุบัน
      current_stop_id: currentStop.stop_id,

      // เวลาอัปเดต
      timestamp: new Date().toISOString()
    }
  };
}

// สร้างข้อมูลรถใหม่
return buses.map(bus => updateBus(bus));

