  if (!existing) {
    latest.set(busId, bus);
    continue;
  }

  const currentTime =
    new Date(bus.updatedAt || bus.timestamp || 0).getTime();

  const existingTime =
    new Date(existing.updatedAt || existing.timestamp || 0).getTime();

  if (currentTime >= existingTime) {
    latest.set(busId, bus);
  }
}

return Array.from(latest.values()).map(bus => ({
