const stops = $('รวมป้ายเป็น 1 item')
  .first()
  .json
  .stops;

const results = [];

for (const bus of buses) {

  const routeStops = stops
    .filter(stop => stop.route_id === bus.route_id)
    .sort(
      (a, b) =>
        Number(a.sequence) -
        Number(b.sequence)
    );

  if (routeStops.length === 0) {
    continue;
  }

  // ป้ายปัจจุบันของรถ
  const currentIndex = routeStops.findIndex(
    stop => stop.stop_id === bus.current_stop_id
  );

  if (currentIndex === -1) {
    continue;
  }

  // หาป้ายก่อนหน้า
  const previousIndex =
    currentIndex === 0
      ? routeStops.length - 1
      : currentIndex - 1;

  const fromStop =
    routeStops[previousIndex];

  const toStop =
    routeStops[currentIndex];

  // ========================================
  // คำนวณระยะทาง
  // ========================================

  function haversine(
    lat1,
    lon1,
    lat2,
    lon2
  ) {

    const R = 6371;

    const dLat =
      (lat2 - lat1) *
      Math.PI / 180;

    const dLon =
      (lon2 - lon1) *
      Math.PI / 180;

    const a =
      Math.sin(dLat / 2) ** 2 +
      Math.cos(lat1 * Math.PI / 180) *
      Math.cos(lat2 * Math.PI / 180) *
      Math.sin(dLon / 2) ** 2;

    const c =
      2 *
      Math.atan2(
        Math.sqrt(a),
        Math.sqrt(1 - a)
      );

    return R * c;
  }

  const distanceKm =
    haversine(
      Number(fromStop.latitude),
      Number(fromStop.longitude),
      Number(toStop.latitude),
      Number(toStop.longitude)
    );


  // ========================================
  // เวลา
  // ========================================

  const timestamp =
    bus.timestamp ||
    new Date().toISOString();

  const date =
    new Date(timestamp);

  const hour =
    date.getHours();

  const dayOfWeek =
    date.toLocaleDateString(
      "th-TH",
      {
        weekday: "long"
      }
    );


  // ========================================
  // Travel Time
  // ========================================
  //
  // ตอนนี้เป็นข้อมูลจำลอง
  // โดยใช้ระยะทาง / ความเร็ว
  //
  // ภายหลังเราจะเปลี่ยนเป็น
  // เวลาที่รถเดินทางจริง
  //

  const speedKmh =
    Number(bus.speed_kmh) || 1;

  const travelTimeMinutes =
    (distanceKm / speedKmh) * 60;


  // ========================================
  // สร้างข้อมูล
  // ========================================

  results.push({

    json: {

      record_id:
        `${bus.bus_id}_${Date.now()}_${toStop.stop_id}`,

      bus_id:
        bus.bus_id,

      route_id:
        bus.route_id,

      from_stop_id:
        fromStop.stop_id,

      from_stop_name:
        fromStop.stop_name,

      to_stop_id:
        toStop.stop_id,

      to_stop_name:
        toStop.stop_name,

      distance_km:
        Number(distanceKm.toFixed(3)),

      speed_kmh:
        Number(speedKmh.toFixed(1)),

      hour:
        hour,

      day_of_week:
        dayOfWeek,

      travel_time_minutes:
        Number(travelTimeMinutes.toFixed(2)),

      timestamp:
        timestamp
    }
  });
}

return results;

