const destinationName = "ตลาดน้อย";

function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371;

  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) *
    Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;

  return R * 2 * Math.atan2(
    Math.sqrt(a),
    Math.sqrt(1 - a)
  );
}

const dayNames = [
  "วันอาทิตย์",
  "วันจันทร์",
  "วันอังคาร",
  "วันพุธ",
  "วันพฤหัสบดี",
  "วันศุกร์",
  "วันเสาร์"
];

const now = new Date();
const results = [];

for (const bus of buses) {

  const routeStops = stops
    .filter(stop =>
      stop.route_id === bus.route_id
    )
    .sort(
      (a, b) =>
        Number(a.sequence) -
        Number(b.sequence)
    );

  if (routeStops.length === 0) continue;

  const currentStop = routeStops.find(
    stop =>
      String(stop.stop_id) ===
      String(bus.current_stop_id)
  );

  if (!currentStop) continue;

  const destinationStop = routeStops.find(
    stop =>
      stop.stop_name === destinationName
  );

  if (!destinationStop) continue;

  const distanceKm = haversine(
    Number(currentStop.latitude),
    Number(currentStop.longitude),
    Number(destinationStop.latitude),
    Number(destinationStop.longitude)
  );

  results.push({
    json: {
      bus_id: bus.bus_id,
      route_id: bus.route_id,

      current_stop_id:
        currentStop.stop_id,

      current_stop_name:
        currentStop.stop_name,

      destination_stop_id:
        destinationStop.stop_id,

      destination_stop_name:
        destinationStop.stop_name,

      distance_km:
        Number(distanceKm.toFixed(3)),

      speed_kmh:
        Number(bus.speed_kmh) || 0,

      hour:
        now.getHours(),

      day_of_week:
        dayNames[now.getDay()],

      timestamp:
        bus.timestamp ||
        now.toISOString()
    }
  });
}

return results;

const buses = $input.all().map(item => item.json);

const latestBuses = new Map();

for (const bus of buses) {
  if (!bus.bus_id) continue;

  const time = new Date(
    bus.timestamp ||
    bus.updatedAt ||
    bus.createdAt ||
    0
  ).getTime();

  const old = latestBuses.get(bus.bus_id);

  if (!old) {
    latestBuses.set(bus.bus_id, bus);
    continue;
  }

  const oldTime = new Date(
    old.timestamp ||
    old.updatedAt ||
    old.createdAt ||
    0
  ).getTime();

  if (time > oldTime) {
    latestBuses.set(bus.bus_id, bus);
  }
}

return Array.from(latestBuses.values())
  .map(bus => ({
    json: bus
  }));
